<template>
 <div class="app-container">
  <header class="packagebar"><h2>包裹发货</h2><el-button size="small" @click="router.push('/erp/order')" v-hasPermi="['erp:order:list']">返回订单工作台</el-button><span>按订单定位包裹；查看收件资料仍须订单详情权限。</span></header>
  <el-alert title="一期一个订单对应一个仓库、一个包裹。填写物流与运单后手工确认发货，表示本地库存出库，不代表平台回传、揽收或妥投。取消请从订单页操作。" type="info" :closable="false" class="mb8"/>
  <el-alert v-if="shipPending" title="发货结果未确认。请用原请求重试，或关闭提示后刷新核对包裹状态，勿换键重复操作。" type="warning" :closable="false" class="mb8"><el-button size="small" :loading="saving" @click="retryShip">原请求重试</el-button><el-button size="small" :disabled="saving" @click="dismissShip">关闭并刷新</el-button></el-alert>
  <el-button size="small" v-hasPermi="['erp:shipment:list']" @click="router.push('/erp/shipment')" :disabled="busy">发货记录</el-button>
  <el-button size="small" v-hasPermi="['erp:picking:list']" @click="router.push('/erp/picking')" :disabled="busy">拣货与扫码复核</el-button>
  <el-form inline size="small" @submit.prevent="search"><el-form-item label="仓库"><ReferenceSelect kind="warehouse" v-model="query.warehouseId" style="width:200px"/></el-form-item><el-form-item label="订单ID"><el-input v-model="orderText" placeholder="正整数，可选" style="width:140px"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:130px"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item><el-button @click="search">查询 / 刷新</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form>
  <div class="packagebar"><span>本页已选 {{selected.length}} 条（最多20）</span><el-button size="small" @click="batchRef.show(selected,'ship')" :disabled="busy||!selected.length" v-hasPermi="['erp:package:ship']">批量确认发货</el-button></div>
  <el-table :data="rows" row-key="packageId" size="small" v-loading="loading" @selection-change="value=>selected=value"><el-table-column type="selection" width="42"/><el-table-column prop="orderId" label="订单ID" width="95"/><el-table-column label="状态" width="100"><template #default="{row}">{{statuses[row.status]||row.status}}</template></el-table-column><el-table-column prop="packageNo" label="包裹号" min-width="235" show-overflow-tooltip/><el-table-column prop="shopId" label="店铺ID" width="90"/><el-table-column prop="warehouseId" label="仓库ID" width="90"/><el-table-column prop="shippedAt" label="发货时间" width="170"/><el-table-column label="操作" width="295" fixed="right"><template #default="{row}"><el-button link type="primary" @click="show(row,false)" :disabled="busy" v-hasPermi="['erp:package:query']">详情</el-button><el-button link type="primary" @click="goOrder(row)" v-if="checkPermi(['erp:order:query'])&&checkPermi(['erp:order:list'])">订单</el-button><el-button v-if="row.status==='READY_TO_SHIP'&&checkPermi(['erp:package:edit'])&&checkPermi(['erp:package:query'])" link type="primary" @click="show(row,true)" :disabled="busy">填运单</el-button><el-button v-if="row.status==='READY_TO_SHIP'" link type="warning" @click="ship(row)" :disabled="busy" v-hasPermi="['erp:package:ship']">确认发货</el-button></template></el-table-column></el-table>
  <p v-if="!loading&&!rows.length" class="empty-hint">当前范围没有包裹。订单审核成功后才会创建包裹；请核对店铺和仓库范围。</p>
  <FulfillmentBatchDialog ref="batchRef" @completed="load"/>
  <el-button size="small" v-if="checkPermi(['erp:salesReturnOrder:list'])" @click="router.push('/erp/salesReturnOrder')">订单退货入库 / 历史</el-button>
  <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/>
  <el-dialog v-model="open" :title="editing?'保存包裹物流':'包裹详情'" class="erp-dialog" width="min(900px, calc(100vw - 24px))" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving" @close="closed">
   <div v-if="detail"><p>{{detail.packageNo}} · 订单 #{{detail.orderId}} · {{statuses[detail.status]}} · 包裹 v{{detail.version}}</p><el-alert title="本页不提供订单收件资料。查看收件人/地址须另有订单详情权限和店铺范围。修改物流也会推进订单版本，取消前请刷新订单。" type="info" :closable="false"/>
    <el-button v-if="detail.status==='SHIPPED'&&checkPermi(['erp:salesReturnOrder:list'])" size="small" @click="router.push({path:'/erp/salesReturnOrder',query:{orderId:String(detail.orderId),packageId:String(detail.packageId)}})">原包裹退货入库 / 历史</el-button>
    <el-alert v-if="saveError" :title="saveError" type="warning" :closable="false" class="mt8"/>
    <el-descriptions v-if="shippingSnapshot" :column="1" size="small"><el-descriptions-item label="保存时物流快照">{{shippingSnapshot.carrierName}} · {{shippingSnapshot.methodName}}（{{shippingSnapshot.methodCode}}）</el-descriptions-item></el-descriptions>
    <el-form label-width="105px" size="small" class="mt8" :disabled="saving||!editing||!!savePending"><el-form-item label="录入方式"><el-radio-group v-model="form.mode"><el-radio value="MANUAL">手工填写</el-radio><el-radio value="CATALOG" :disabled="!logisticsAvailable||saving||!editing||!!savePending">目录选择</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.mode==='CATALOG'" label="配送方式"><LogisticsMethodSelect v-model="form.shippingMethodId" :initial-label="shippingSnapshot?shippingSnapshot.carrierName+' · '+shippingSnapshot.methodName:''"/></el-form-item><el-form-item v-else label="物流代码"><el-input v-model="form.carrierCode" maxlength="64" placeholder="例如 MANUAL / SF / EMS（仅手工标签）"/></el-form-item><el-form-item label="运单号"><el-input v-model="form.trackingNo" maxlength="128" placeholder="文本保留前导零"/></el-form-item></el-form>
    <el-table :data="detail.lines" size="small"><el-table-column prop="orderLineId" label="订单行" width="90"/><el-table-column prop="skuCode" label="内部SKU" width="160"/><el-table-column prop="productName" label="商品快照"/><el-table-column prop="unit" label="单位" width="80"/><el-table-column prop="quantity" label="数量" width="100"/></el-table>
   </div><template #footer><el-button v-if="detail&&checkPermi(['erp:order:list'])&&checkPermi(['erp:order:query'])" @click="goOrder(detail)" :disabled="saving">查看订单详情</el-button><el-button @click="open=false" :disabled="saving">关闭</el-button><el-button v-if="editing" type="primary" @click="save" :loading="saving">{{savePending?'原请求重试':'保存物流信息'}}</el-button></template>
  </el-dialog>
 </div>
</template>
<script setup>
import { ref, reactive, computed, onMounted,watch,onBeforeUnmount,onDeactivated,onActivated } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { checkPermi } from '@/utils/permission'
import ReferenceSelect from './ReferenceSelect.vue'
import FulfillmentBatchDialog from './FulfillmentBatchDialog.vue'
import LogisticsMethodSelect from './LogisticsMethodSelect.vue'
import {packageShipping,savePackageShipping,checkTracking} from '@/api/erp/logistics'
import {logisticsKey,packageLogisticsCommand,logisticsCommand,logisticsRefused} from '@/utils/logistics.mjs'
import { listPackages, getPackage, savePackageLogistics, shipPackage } from '@/api/erp/order'
const rows=ref([]),total=ref(0),loading=ref(false),saving=ref(false),detailLoading=ref(false),open=ref(false),editing=ref(false),detail=ref(null),form=ref({}),orderText=ref('')
const selected=ref([]),batchRef=ref(),router=useRouter(),route=useRoute()
const savePending=ref(null),saveError=ref(''),shipPending=ref(null),shippingSnapshot=ref(null),logisticsAvailable=ref(false)
const busy=computed(()=>saving.value||detailLoading.value||!!savePending.value||!!shipPending.value),query=reactive({pageNum:1,pageSize:10,warehouseId:undefined,orderId:undefined,status:''}),statuses={READY_TO_SHIP:'待发货',SHIPPED:'已发货',CANCELLED:'已取消'}
let listSequence=0,detailSequence=0,linkSequence=0,actionSequence=0,active=true
let wasDeactivated=false
function clearDetail(){++detailSequence;detailLoading.value=false;detail.value=null;form.value={};shippingSnapshot.value=null;savePending.value=null;saveError.value='';logisticsAvailable.value=false}
async function load(){if(!active)return;const ticket=++listSequence;loading.value=true;try{const r=await listPackages({...query});if(active&&ticket===listSequence){rows.value=r.rows;total.value=r.total;selected.value=[]}}catch{if(active&&ticket===listSequence){rows.value=[];total.value=0;selected.value=[];open.value=false;clearDetail()}}finally{if(ticket===listSequence)loading.value=false}}
function search(){++linkSequence;if(orderText.value&&(!/^[1-9]\d*$/.test(orderText.value)||!Number.isSafeInteger(Number(orderText.value)))){ElMessage.warning('订单ID须为可精确表示的正整数');return}query.orderId=orderText.value?Number(orderText.value):undefined;query.pageNum=1;return load()}
function reset(){orderText.value='';Object.assign(query,{warehouseId:undefined,orderId:undefined,status:''});return search()}
async function show(row,edit){if(!active||busy.value)return;clearDetail();const ticket=++detailSequence;detailLoading.value=true;try{const [r,s]=await Promise.all([getPackage(row.packageId),packageShipping(row.packageId)]);if(!active||ticket!==detailSequence)return;if(row.orderId&&r.data.orderId!==row.orderId){ElMessage.warning('包裹与链接订单不一致');return}if(s.data&&s.data.packageVersion!==r.data.version){ElMessage.warning('包裹物流已变化，请刷新后重试');return}detail.value=r.data;shippingSnapshot.value=s.data?.snapshot||null;logisticsAvailable.value=s.data?.available===true;editing.value=edit&&r.data.status==='READY_TO_SHIP';form.value={mode:shippingSnapshot.value?'CATALOG':'MANUAL',shippingMethodId:shippingSnapshot.value?.shippingMethodId,carrierCode:r.data.carrierCode,trackingNo:r.data.trackingNo,requestKey:logisticsKey()};open.value=true}catch{if(active&&ticket===detailSequence){rows.value=[];total.value=0;open.value=false;clearDetail()}}finally{if(ticket===detailSequence)detailLoading.value=false}}
function goOrder(row){if(checkPermi(['erp:order:list'])&&checkPermi(['erp:order:query']))return router.push({path:'/erp/order',query:{orderId:String(row.orderId)}})}
function safeID(raw){return typeof raw==='string'&&/^[1-9]\d*$/.test(raw)&&Number.isSafeInteger(Number(raw))?Number(raw):null}
async function followPackageLink(){if(!active||saving.value)return;const ticket=++linkSequence;open.value=false;clearDetail();shipPending.value=null;const order=route.query.orderId,pack=route.query.packageId;if((order!==undefined&&!safeID(order))||(pack!==undefined&&!safeID(pack))){++listSequence;rows.value=[];total.value=0;ElMessage.warning('包裹链接编号无效');return}orderText.value=order||'';query.orderId=order?safeID(order):undefined;query.pageNum=1;try{await load();if(!active||ticket!==linkSequence||!pack)return;if(!checkPermi(['erp:package:query'])){ElMessage.warning('查看包裹需要包裹详情权限');return}await show({packageId:safeID(pack),orderId:query.orderId},false)}catch{}}
watch(()=>[route.query.orderId,route.query.packageId],followPackageLink)
function deactivate(){active=false;++listSequence;++linkSequence;++actionSequence;loading.value=false;saving.value=false;open.value=false;clearDetail();shipPending.value=null;rows.value=[];total.value=0;selected.value=[]}
onBeforeUnmount(deactivate);onDeactivated(()=>{wasDeactivated=true;deactivate()});onActivated(()=>{if(wasDeactivated){wasDeactivated=false;active=true;return followPackageLink()}})
function closed(){if(open.value)return;clearDetail()}
async function save(){if(!active||saving.value||!open.value||!editing.value||!detail.value)return;let command=savePending.value;try{if(!command)command=packageLogisticsCommand(detail.value,{...form.value,mode:form.value.mode||'MANUAL'})}catch(e){ElMessage.warning(e.message);return}const ticket=detailSequence,operation=++actionSequence;saving.value=true;try{
 if(!savePending.value&&command.kind==='CATALOG'){try{const r=await checkTracking({packageId:command.id,shippingMethodId:command.payload.shippingMethodId,trackingNo:command.payload.trackingNo});if(!active||ticket!==detailSequence||operation!==actionSequence)return;if(r.data.duplicate){try{await ElMessageBox.confirm('当前可见包裹中已有相同物流代码及运单号。确认继续保存？','重复运单提示',{type:'warning'})}catch{return}}}catch(e){if(!active||ticket!==detailSequence||operation!==actionSequence)return;if(logisticsRefused(e)){open.value=false;clearDetail();rows.value=[];total.value=0}else ElMessage.warning('运单提示检查未完成，尚未保存');return}}
 if(!active||ticket!==detailSequence||operation!==actionSequence)return;savePending.value=command;await(command.kind==='CATALOG'?savePackageShipping(command.id,command.payload):savePackageLogistics(command.id,command.payload));if(!active||ticket!==detailSequence||operation!==actionSequence)return;open.value=false;clearDetail();ElMessage.success('物流已保存，尚未发货');await load()
 }catch(e){if(!active||ticket!==detailSequence||operation!==actionSequence)return;if(logisticsRefused(e)){open.value=false;clearDetail();rows.value=[];total.value=0}else saveError.value='请求结果未确认，表单已冻结。请用原请求重试，或关闭后刷新包裹。'}finally{if(operation===actionSequence)saving.value=false}}
async function performShip(command,ticket,operation){try{if(!active||ticket!==linkSequence||operation!==actionSequence)return;await shipPackage(command.id,command.payload);if(!active||ticket!==linkSequence||operation!==actionSequence)return;shipPending.value=null;ElMessage.success('本地发货出库已完成');await load()}catch(e){if(!active||ticket!==linkSequence||operation!==actionSequence)return;if(logisticsRefused(e)){shipPending.value=null;rows.value=[];total.value=0;open.value=false;clearDetail()}}finally{if(operation===actionSequence)saving.value=false}}
async function ship(row){if(!active||busy.value)return;const command=logisticsCommand('SHIP',row.packageId,{version:row.version,requestKey:logisticsKey()}),ticket=linkSequence,operation=++actionSequence;saving.value=true;try{await ElMessageBox.confirm('确认包裹已交付出库？成功后原子扣减实物和预占库存，订单不可取消。这里只登记本地发货，不会回传平台。','确认发货',{type:'warning'})}catch{if(operation===actionSequence)saving.value=false;return}if(!active||ticket!==linkSequence||operation!==actionSequence){if(operation===actionSequence)saving.value=false;return}shipPending.value=command;return performShip(command,ticket,operation)}
async function retryShip(){if(!active||saving.value||!shipPending.value)return;const operation=++actionSequence;saving.value=true;return performShip(shipPending.value,linkSequence,operation)}
async function dismissShip(){if(!active||saving.value)return;shipPending.value=null;return load()}
onMounted(followPackageLink)
</script>
<style scoped>
.packagebar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.packagebar h2{font-size:18px;margin:0 10px 0 0}.packagebar span,.empty-hint{font-size:12px;color:var(--el-text-color-secondary)} :deep(.el-dialog__body){max-height:calc(100dvh - 200px);overflow:auto} :deep(.el-table .cell){line-height:22px}
</style>
